// Idle tracking and step events for the benchmark. A step ends when no
// tracked promise (simulated request, telemetry flush, lazy chunk) is
// pending, no debounced call is waiting, and no React root has scheduled
// work.

const pending = new Set();
const roots = new Set();
let version = 0;

// Created on first use: an open port would keep the server build's Node
// process alive.
let channel = null;
const taskQueue = [];

// Runs `callback` in a task of its own, without the clamping of nested
// timers.
export function afterTask(callback) {
    if (!channel) {
        channel = new MessageChannel();
        channel.port1.onmessage = () => taskQueue.shift()?.();
    }
    taskQueue.push(callback);
    channel.port2.postMessage(null);
}

export function nextTask() {
    return new Promise((resolve) => afterTask(resolve));
}

export function track(promise) {
    pending.add(promise);
    version++;
    const done = () => pending.delete(promise);
    promise.then(done, done);
    return promise;
}

// Lets whenIdle() see a React root's pending work (private fields of React
// DOM's root).
export function trackReactRoot(root) {
    roots.add(root._internalRoot);
}

function reactIdle() {
    for (const root of roots) {
        if (root.pendingLanes !== 0 || root.callbackNode !== null)
            return false;
    }
    return true;
}

export async function whenIdle() {
    for (;;) {
        const start = version;
        while (pending.size)
            await Promise.allSettled([...pending]);
        // React's scheduler and passive effects run in tasks of their own,
        // and Apollo's useFragment re-renders from a zero-delay timer.
        await nextTask();
        await new Promise((resolve) => setTimeout(resolve, 0));
        await nextTask();
        if (!pending.size && reactIdle() && version === start)
            return;
    }
}

export function emitStepEvent(name, detail) {
    if (typeof window !== "undefined")
        window.dispatchEvent(new CustomEvent(`travel-${name}`, { detail }));
}

export function nextEvent(name) {
    return new Promise((resolve) => window.addEventListener(name, (event) => resolve(event.detail), { once: true }));
}
