// The frozen clock. App code asks this module for "now" and "today" instead
// of Date.now(), so that the date picker and relative dates are the same in
// every run.
import { getPageConfig } from "./env.js";

const DAY = 86400000;

export function today() {
    return getPageConfig().today;
}

export function now() {
    return Date.parse(`${today()}T09:00:00Z`);
}

export function parseDay(day) {
    return new Date(`${day}T00:00:00Z`);
}

export function formatDay(date) {
    return date.toISOString().slice(0, 10);
}

export function addDays(day, count) {
    return formatDay(new Date(parseDay(day).getTime() + count * DAY));
}

export function daysBetween(from, to) {
    return Math.round((parseDay(to) - parseDay(from)) / DAY);
}

export function addMonths(month, count) {
    const date = parseDay(`${month}-01`);
    date.setUTCMonth(date.getUTCMonth() + count);
    return formatDay(date).slice(0, 7);
}
