import { forwardRef, useCallback, useRef } from "react";
import { useTrack } from "./TrackingProvider.jsx";

// Wraps an interactive component so that its clicks are tracked with the
// surrounding tracking scope: `trackingName` and `trackingData` props name
// the event.
export function withTracking(Component, defaultName) {
    const Tracked = forwardRef(function Tracked({ trackingName = defaultName, trackingData, onClick, ...props }, ref) {
        const track = useTrack();
        const clicks = useRef(0);
        const handleClick = useCallback((event) => {
            clicks.current++;
            track(`${trackingName}.click`, { ...trackingData, count: clicks.current });
            onClick?.(event);
        }, [track, trackingName, trackingData, onClick]);
        return <Component ref={ref} {...props} onClick={handleClick} />;
    });
    Tracked.displayName = `withTracking(${Component.displayName ?? Component.name})`;
    return Tracked;
}
